/// <summary>
/// C99 <c>&lt;stdlib.h&gt;</c> surface beyond the four primitives already in
/// <see cref="Libc"/> proper (<c>malloc</c> / <c>free</c> + <c>strtod</c> /
/// <c>atof</c>): integer string-conversion, integer arithmetic helpers,
/// allocation extras, pseudo-random numbers, environment access, program
/// control, and generic <c>qsort</c> / <c>bsearch</c>.
/// </summary>
/// <remarks>
/// The <c>div_t</c> / <c>ldiv_t</c> / <c>lldiv_t</c> result structs are
/// pre-registered as known type names (<c>Compiler.PredefinedTypeNames</c>) so
/// emitted user code can spell them without a typedef. <c>qsort</c> /
/// <c>bsearch</c> take a C# function pointer (<c>delegate*</c>) for the
/// comparator — AOT-clean, no delegate allocation — which dotcc produces by
/// decaying a bare comparator name to <c>&amp;cmp</c> at the call site.
/// </remarks>
public static unsafe partial class Libc
{
    // div/ldiv/lldiv result structs. dotcc maps C `long` and `long long` both
    // to C# `long` (LP64), so ldiv_t and lldiv_t share a shape but stay
    // distinct named types so user code's spelling resolves.

    /// <summary><c>div_t</c> — quotient/remainder pair for <see cref="div"/>.</summary>
    public struct div_t { public int quot; public int rem; }

    /// <summary><c>ldiv_t</c> — quotient/remainder pair for <see cref="ldiv"/>.</summary>
    public struct ldiv_t { public long quot; public long rem; }

    /// <summary><c>lldiv_t</c> — quotient/remainder pair for <see cref="lldiv"/>.</summary>
    public struct lldiv_t { public long quot; public long rem; }

    // ---------------------------------------------------------------------
    // String → integer conversions
    // ---------------------------------------------------------------------

    private static int DigitVal(byte b)
    {
        if (b >= (byte)'0' && b <= (byte)'9') { return b - '0'; }
        if (b >= (byte)'a' && b <= (byte)'z') { return b - 'a' + 10; }
        if (b >= (byte)'A' && b <= (byte)'Z') { return b - 'A' + 10; }
        return -1;
    }

    /// <summary>Skip leading C-locale whitespace, then resolve the effective
    /// base: <paramref name="base"/> 0 auto-detects (<c>0x</c>→16, leading
    /// <c>0</c>→8, else 10), and base 16 tolerates an optional <c>0x</c> prefix.
    /// Advances <paramref name="p"/> past any consumed prefix.</summary>
    private static int NormalizeBase(ref byte* p, int @base)
    {
        while (*p == (byte)' ' || (*p >= 9 && *p <= 13)) { p++; }
        // The sign is parsed by the caller before this; here p sits at the
        // first magnitude byte.
        if (@base == 0)
        {
            if (*p == (byte)'0')
            {
                if (p[1] == (byte)'x' || p[1] == (byte)'X') { p += 2; return 16; }
                return 8;   // leading '0' is consumed later as octal digit 0
            }
            return 10;
        }
        if (@base == 16 && *p == (byte)'0' && (p[1] == (byte)'x' || p[1] == (byte)'X')) { p += 2; }
        return @base;
    }

    /// <summary>Signed 64-bit core shared by strtol/strtoll (dotcc's
    /// <c>long</c> == <c>long long</c> == 64-bit). Clamps to LONG_MIN/MAX and
    /// sets <see cref="errno"/> to ERANGE on overflow.</summary>
    private static long StrtollCore(byte* nptr, byte** endptr, int @base)
    {
        byte* p = nptr;
        while (*p == (byte)' ' || (*p >= 9 && *p <= 13)) { p++; }
        bool neg = false;
        if (*p == (byte)'+' || *p == (byte)'-') { neg = *p == (byte)'-'; p++; }

        @base = NormalizeBase(ref p, @base);

        ulong cutoff = neg ? (ulong)long.MaxValue + 1UL : (ulong)long.MaxValue;
        ulong cutlim = cutoff % (ulong)@base;
        cutoff /= (ulong)@base;

        bool any = false, overflow = false;
        ulong acc = 0;
        for (; ; p++)
        {
            int d = DigitVal(*p);
            if (d < 0 || d >= @base) { break; }
            any = true;
            if (overflow) { continue; }
            if (acc > cutoff || (acc == cutoff && (ulong)d > cutlim)) { overflow = true; continue; }
            acc = acc * (ulong)@base + (ulong)d;
        }

        if (endptr != null) { *endptr = any ? p : nptr; }
        if (overflow) { errno = ERANGE; return neg ? long.MinValue : long.MaxValue; }
        return unchecked((long)(neg ? 0UL - acc : acc));
    }

    /// <summary>Unsigned 64-bit core shared by strtoul/strtoull. Clamps to
    /// ULONG_MAX and sets <see cref="errno"/> to ERANGE on overflow. A leading
    /// minus negates the result modulo 2^64 (per C).</summary>
    private static ulong StrtoullCore(byte* nptr, byte** endptr, int @base)
    {
        byte* p = nptr;
        while (*p == (byte)' ' || (*p >= 9 && *p <= 13)) { p++; }
        bool neg = false;
        if (*p == (byte)'+' || *p == (byte)'-') { neg = *p == (byte)'-'; p++; }

        @base = NormalizeBase(ref p, @base);

        ulong cutoff = ulong.MaxValue / (ulong)@base;
        ulong cutlim = ulong.MaxValue % (ulong)@base;

        bool any = false, overflow = false;
        ulong acc = 0;
        for (; ; p++)
        {
            int d = DigitVal(*p);
            if (d < 0 || d >= @base) { break; }
            any = true;
            if (overflow) { continue; }
            if (acc > cutoff || (acc == cutoff && (ulong)d > cutlim)) { overflow = true; continue; }
            acc = acc * (ulong)@base + (ulong)d;
        }

        if (endptr != null) { *endptr = any ? p : nptr; }
        if (overflow) { errno = ERANGE; return ulong.MaxValue; }
        return neg ? 0UL - acc : acc;
    }

    /// <summary><c>strtol(nptr, endptr, base)</c> — parse a signed long.</summary>
    public static long strtol(byte* nptr, byte** endptr, int @base) => StrtollCore(nptr, endptr, @base);

    /// <summary><c>strtoll(nptr, endptr, base)</c> (C99) — parse a signed long long
    /// (== <c>strtol</c> on dotcc's LP64 model).</summary>
    public static long strtoll(byte* nptr, byte** endptr, int @base) => StrtollCore(nptr, endptr, @base);

    /// <summary><c>strtoul(nptr, endptr, base)</c> — parse an unsigned long.</summary>
    public static ulong strtoul(byte* nptr, byte** endptr, int @base) => StrtoullCore(nptr, endptr, @base);

    /// <summary><c>strtoull(nptr, endptr, base)</c> (C99) — parse an unsigned long long.</summary>
    public static ulong strtoull(byte* nptr, byte** endptr, int @base) => StrtoullCore(nptr, endptr, @base);

    /// <summary><c>atoi(nptr)</c> ≡ <c>(int)strtol(nptr, NULL, 10)</c>.</summary>
    public static int atoi(byte* nptr) => unchecked((int)StrtollCore(nptr, null, 10));

    /// <summary><c>atol(nptr)</c> ≡ <c>strtol(nptr, NULL, 10)</c>.</summary>
    public static long atol(byte* nptr) => StrtollCore(nptr, null, 10);

    /// <summary><c>atoll(nptr)</c> (C99) ≡ <c>strtoll(nptr, NULL, 10)</c>.</summary>
    public static long atoll(byte* nptr) => StrtollCore(nptr, null, 10);

    // ---------------------------------------------------------------------
    // Integer arithmetic
    // ---------------------------------------------------------------------

    /// <summary><c>abs(n)</c> — absolute value. UB at INT_MIN (wraps, per C —
    /// no exception, unlike <see cref="Math.Abs(int)"/>).</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static int abs(int n) => n < 0 ? unchecked(-n) : n;

    /// <summary><c>labs(n)</c> — absolute value of a long.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static long labs(long n) => n < 0 ? unchecked(-n) : n;

    /// <summary><c>llabs(n)</c> (C99) — absolute value of a long long.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static long llabs(long n) => n < 0 ? unchecked(-n) : n;

    /// <summary><c>div(num, den)</c> — quotient + remainder. Both truncate
    /// toward zero (C99), matching C#'s <c>/</c> and <c>%</c>.</summary>
    public static div_t div(int num, int den) => new div_t { quot = num / den, rem = num % den };

    /// <summary><c>ldiv(num, den)</c> — long quotient + remainder.</summary>
    public static ldiv_t ldiv(long num, long den) => new ldiv_t { quot = num / den, rem = num % den };

    /// <summary><c>lldiv(num, den)</c> (C99) — long long quotient + remainder.</summary>
    public static lldiv_t lldiv(long num, long den) => new lldiv_t { quot = num / den, rem = num % den };

    // ---------------------------------------------------------------------
    // Allocation extras (malloc / free live in Libc.cs)
    // ---------------------------------------------------------------------

    /// <summary><c>calloc(n, size)</c> — allocate <c>n * size</c> zero-filled
    /// bytes. Returns null on allocation failure or size-product overflow.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void* calloc(int n, int size)
    {
        nuint count = (nuint)n, elementSize = (nuint)size;
        if (elementSize != 0 && count > nuint.MaxValue / elementSize) { return null; }
        return AllocateHeap(count * elementSize, true);
    }

    /// <summary>LP64 size_t entry point; rejects overflowing products before allocation.</summary>
    public static void* calloc(ulong n, ulong size)
    {
        if (size != 0 && n > (ulong)nuint.MaxValue / size) return null;
        return AllocateHeap((nuint)(n * size), true);
    }

    /// <summary><c>realloc(p, size)</c> — resize a prior allocation, preserving
    /// contents up to the smaller of old/new size. Routes to
    /// <see cref="NativeMemory.Realloc(void*, nuint)"/>. On allocation failure,
    /// returns null and preserves the original allocation.</summary>
    [MethodImpl(MethodImplOptions.AggressiveInlining)]
    public static void* realloc(void* p, int size)
    {
        return ReallocateHeap(p, (nuint)size);
    }

    /// <summary>LP64 size_t entry point, preserving the old allocation on failure.</summary>
    public static void* realloc(void* p, ulong size) => size > (ulong)nuint.MaxValue ? null : ReallocateHeap(p, (nuint)size);

    // ---------------------------------------------------------------------
    // Pseudo-random numbers
    // ---------------------------------------------------------------------

    /// <summary><c>RAND_MAX</c> — the largest value <see cref="rand"/> returns.
    /// 32767, the C-mandated minimum (and MSVC's value) for portability.</summary>
    public const int RAND_MAX = 32767;

    [ThreadStatic]
    private static Random? _rand;

    /// <summary><c>rand()</c> — pseudo-random int in <c>[0, RAND_MAX]</c>. Uses a
    /// generator shared by the bound program's threads; legacy unbound calls
    /// retain their thread-local generator. Seeded as if <c>srand(1)</c> until <see cref="srand"/> is called,
    /// per C. Note: the .NET PRNG differs from any C library's, so sequences are
    /// not byte-compatible with gcc/MSVC — only the contract (range, determinism
    /// per seed) holds.</summary>
    public static int rand()
    {
        if (OwnedRandom is { } state)
        {
            lock (state.Gate) return state.Rand.Next(0, RAND_MAX + 1);
        }
        _rand ??= new Random(1);
        return _rand.Next(0, RAND_MAX + 1);
    }

    /// <summary><c>srand(seed)</c> — reseed <see cref="rand"/>. Takes a wide
    /// integer so any C integer argument (incl. <c>(unsigned)time(NULL)</c>)
    /// widens in without a cast; truncated to unsigned-int per C.</summary>
    public static void srand(long seed)
    {
        var random = new Random(unchecked((int)(uint)seed));
        if (OwnedRandom is { } state) { lock (state.Gate) state.Rand = random; }
        else _rand = random;
    }

    // ---------------------------------------------------------------------
    // Environment + program control
    // ---------------------------------------------------------------------

    [ThreadStatic] private static byte* _envBuf;
    [ThreadStatic] private static int _envCap;

    /// <summary>Copy a managed string into a thread-local native buffer as
    /// NUL-terminated UTF-8 and return a pointer to it. The buffer is reused
    /// across calls (matching C's "may be overwritten by a later call"
    /// contract for <c>getenv</c>).</summary>
    private static byte* StashCString(string? s)
    {
        if (s is null) { return null; }
        int need = Encoding.UTF8.GetByteCount(s) + 1;
        if (_envBuf == null || _envCap < need)
        {
            if (_envBuf != null) { NativeMemory.Free(_envBuf); }
            _envCap = need;
            _envBuf = (byte*)NativeMemory.Alloc((nuint)need);
        }
        int n = Encoding.UTF8.GetBytes(s, new Span<byte>(_envBuf, _envCap));
        _envBuf[n] = 0;
        return _envBuf;
    }

    /// <summary><c>getenv(name)</c> — look up an environment variable; returns a
    /// pointer to its value (in a reused thread-local buffer) or <c>null</c> if
    /// unset. Routes to <see cref="Environment.GetEnvironmentVariable(string)"/>.</summary>
    public static byte* getenv(byte* name)
    {
        var key = Encoding.UTF8.GetString(name, strlen(name));
        return StashCString(Environment.GetEnvironmentVariable(key));
    }

    /// <summary>POSIX <c>setenv(name, value, overwrite)</c> — add or change an
    /// environment variable; returns 0 on success, -1 (EINVAL) if <paramref
    /// name="name"/> is null/empty or contains <c>'='</c>. When <paramref
    /// name="overwrite"/> is 0 and the name already exists the value is left
    /// untouched. Routes to <see cref="Environment.SetEnvironmentVariable(string,string)"/>
    /// (chibi's <c>(chibi ast)</c> env-cell support uses it).</summary>
    public static int setenv(byte* name, byte* value, int overwrite)
    {
        if (name == null || *name == 0) { errno = EINVAL; return -1; }
        var key = Encoding.UTF8.GetString(name, strlen(name));
        if (key.IndexOf('=') >= 0) { errno = EINVAL; return -1; }
        if (overwrite == 0 && Environment.GetEnvironmentVariable(key) != null) { return 0; }
        Environment.SetEnvironmentVariable(key, value == null ? string.Empty : Encoding.UTF8.GetString(value, strlen(value)));
        return 0;
    }

    /// <summary>POSIX <c>unsetenv(name)</c> — remove an environment variable;
    /// returns 0 on success, -1 (EINVAL) if <paramref name="name"/> is null/empty
    /// or contains <c>'='</c>. Removing an unset name is not an error. Routes to
    /// <see cref="Environment.SetEnvironmentVariable(string,string)"/> with a null
    /// value.</summary>
    public static int unsetenv(byte* name)
    {
        if (name == null || *name == 0) { errno = EINVAL; return -1; }
        var key = Encoding.UTF8.GetString(name, strlen(name));
        if (key.IndexOf('=') >= 0) { errno = EINVAL; return -1; }
        Environment.SetEnvironmentVariable(key, null);
        return 0;
    }

    private static byte** _environ;
    private static readonly Lock _environLock = new();

    /// <summary>POSIX <c>char **environ</c> — the whole process environment as a
    /// NULL-terminated array of NUL-terminated <c>"NAME=value"</c> UTF-8 strings.
    /// Built lazily from <see cref="Environment.GetEnvironmentVariables"/> and
    /// cached (a one-shot snapshot — dotcc doesn't reflect later <c>setenv</c>
    /// mutations through it, which is enough for the read-only iterators that use
    /// it). SRFI-98's <c>get-environment-variables</c> walks it; surfaced by bare
    /// name through <c>using static Libc</c> so a program's <c>extern char
    /// **environ;</c> resolves here. Double-checked lock: concurrent first-callers
    /// build one shared array, not two (parallel tests / a threaded program).</summary>
    public static byte** environ
    {
        get
        {
            var existing = _environ;
            if (existing != null) { return existing; }
            lock (_environLock)
            {
                // `??=` isn't valid on a pointer type — explicit check.
                if (_environ == null) { _environ = BuildEnviron(); }
                return _environ;
            }
        }
    }

    private static byte** BuildEnviron()
    {
        var vars = Environment.GetEnvironmentVariables();
        var arr = (byte**)NativeMemory.Alloc((nuint)(vars.Count + 1), (nuint)sizeof(byte*));
        var i = 0;
        foreach (global::System.Collections.DictionaryEntry e in vars)
        {
            var entry = $"{e.Key}={e.Value}";
            var need = Encoding.UTF8.GetByteCount(entry) + 1;
            var p = (byte*)NativeMemory.Alloc((nuint)need);
            var n = Encoding.UTF8.GetBytes(entry, new Span<byte>(p, need));
            p[n] = 0;
            arr[i++] = p;
        }
        arr[i] = null;
        return arr;
    }

    /// <summary><c>exit(code)</c> — terminate the program with
    /// <paramref name="code"/>. A bound program records and throws an owning
    /// termination request; an unbound program uses Environment.Exit.
    /// dotcc does not yet run <c>atexit</c> handlers.</summary>
    [global::System.Diagnostics.CodeAnalysis.DoesNotReturn]
    public static void exit(int code) => TerminateRuntime(RuntimeTerminationKind.Exit, code);

    /// <summary><c>_Exit(code)</c> (C99) — terminate immediately without flushing
    /// or running handlers. Same backing as <see cref="exit"/> here.</summary>
    [global::System.Diagnostics.CodeAnalysis.DoesNotReturn]
    public static void _Exit(int code) => TerminateRuntime(RuntimeTerminationKind.ImmediateExit, code);

    /// <summary><c>abort()</c> records abnormal termination for an explicitly
    /// bound program; unbound calls retain Environment.FailFast behavior.</summary>
    [global::System.Diagnostics.CodeAnalysis.DoesNotReturn]
    public static void abort() => TerminateRuntime(RuntimeTerminationKind.Abort, 0);

    /// <summary>
    /// <c>system(command)</c> — hand <paramref name="command"/> to the host
    /// command interpreter and return its exit status. With a null command,
    /// returns nonzero (a command processor is available). On a launch failure
    /// returns -1, matching the C library.
    /// </summary>
    /// <remarks>
    /// Backed by <see cref="System.Diagnostics.Process"/>, the only libc entry
    /// that spawns a child process. It costs nothing in programs that don't call
    /// it: <c>Process</c> ships in the shared framework (no extra dependency),
    /// and under NativeAOT the trimmer drops this method — and <c>Process</c>
    /// with it — when nothing reaches it. The interpreter matches the platform's
    /// CRT: <c>cmd.exe /c …</c> on Windows, <c>/bin/sh -c …</c> elsewhere. We set
    /// <c>UseShellExecute = false</c> with an explicit executable, which keeps
    /// the call AOT-analyzer-clean (no <c>[RequiresUnreferencedCode]</c> path).
    /// </remarks>
    public static int system(byte* command)
    {
        // C: system(NULL) probes for a command processor — we always have one.
        if (command == null) { return 1; }
        var cmd = Encoding.UTF8.GetString(command, strlen(command));
        var psi = new global::System.Diagnostics.ProcessStartInfo { UseShellExecute = false, WorkingDirectory = CurrentWorkingDirectory };
        if (OperatingSystem.IsWindows())
        {
            // Mirror the MSVC CRT: ComSpec (cmd.exe) with /c, the whole string
            // handed to cmd verbatim so cmd does the parsing (system's contract).
            psi.FileName = Environment.GetEnvironmentVariable("ComSpec") ?? "cmd.exe";
            psi.Arguments = "/c " + cmd;
        }
        else
        {
            // POSIX: /bin/sh -c "<command>" — ArgumentList keeps the command a
            // single argv entry so the shell, not .NET, splits it.
            psi.FileName = "/bin/sh";
            psi.ArgumentList.Add("-c");
            psi.ArgumentList.Add(cmd);
        }
        try
        {
            using var proc = global::System.Diagnostics.Process.Start(psi);
            if (proc == null) { return -1; }
            proc.WaitForExit();
            return proc.ExitCode;
        }
        catch
        {
            return -1; // couldn't launch the interpreter
        }
    }

    // ---------------------------------------------------------------------
    // Generic sort / search (function-pointer comparator)
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>qsort(base, n, size, cmp)</c> — sort <paramref name="n"/> elements of
    /// <paramref name="size"/> bytes in place using the comparator
    /// <paramref name="cmp"/> (returns &lt;0 / 0 / &gt;0). Implemented as an
    /// in-place insertion sort (stable, O(n²)) — correct for the contract; the
    /// element-swap temp comes from a single scratch allocation.
    /// </summary>
    public static void qsort(void* @base, int n, int size, delegate*<void*, void*, int> cmp)
    {
        if (n < 2 || size <= 0) { return; }
        byte* b = (byte*)@base;
        byte* tmp = (byte*)NativeMemory.Alloc((nuint)size);
        for (int i = 1; i < n; i++)
        {
            Buffer.MemoryCopy(b + (long)i * size, tmp, size, size);
            int j = i - 1;
            while (j >= 0 && cmp(b + (long)j * size, tmp) > 0)
            {
                Buffer.MemoryCopy(b + (long)j * size, b + (long)(j + 1) * size, size, size);
                j--;
            }
            Buffer.MemoryCopy(tmp, b + (long)(j + 1) * size, size, size);
        }
        NativeMemory.Free(tmp);
    }

    /// <summary>
    /// <c>bsearch(key, base, n, size, cmp)</c> — binary-search a sorted array.
    /// Returns a pointer to a matching element or <c>null</c>. The array must be
    /// sorted consistently with <paramref name="cmp"/>.
    /// </summary>
    public static void* bsearch(void* key, void* @base, int n, int size, delegate*<void*, void*, int> cmp)
    {
        byte* b = (byte*)@base;
        int lo = 0, hi = n - 1;
        while (lo <= hi)
        {
            int mid = lo + (hi - lo) / 2;
            byte* el = b + (long)mid * size;
            int c = cmp(key, el);
            if (c < 0) { hi = mid - 1; }
            else if (c > 0) { lo = mid + 1; }
            else { return el; }
        }
        return null;
    }

    /// <summary>Instance callback ABI: forwards the same explicit owner to every
    /// comparison and keeps its runtime alive until sorting finishes.</summary>
    public static void qsort<T>(T instance, void* @base, int n, int size,
        delegate*<T, void*, void*, int> cmp) where T : class, IProgramInstance
    {
        ArgumentNullException.ThrowIfNull(instance);
        if (n < 2 || size <= 0) return;
        RuntimeContext context = instance.__DotCcRuntime;
        context.Retain();
        byte* temporary = null;
        try
        {
            byte* bytes = (byte*)@base;
            temporary = (byte*)NativeMemory.Alloc((nuint)size);
            for (int i = 1; i < n; ++i)
            {
                Buffer.MemoryCopy(bytes + (long)i * size, temporary, size, size);
                int j = i - 1;
                while (j >= 0 && cmp(instance, bytes + (long)j * size, temporary) > 0)
                {
                    Buffer.MemoryCopy(bytes + (long)j * size, bytes + (long)(j + 1) * size, size, size);
                    --j;
                }
                Buffer.MemoryCopy(temporary, bytes + (long)(j + 1) * size, size, size);
            }
        }
        finally { NativeMemory.Free(temporary); context.Release(); }
    }

    /// <summary>Instance callback ABI for binary search. Comparator adapters bind
    /// the supplied owner; the surrounding ambient context is not the identity.</summary>
    public static void* bsearch<T>(T instance, void* key, void* @base, int n, int size,
        delegate*<T, void*, void*, int> cmp) where T : class, IProgramInstance
    {
        ArgumentNullException.ThrowIfNull(instance);
        RuntimeContext context = instance.__DotCcRuntime;
        context.Retain();
        try
        {
            byte* bytes = (byte*)@base;
            int lo = 0, hi = n - 1;
            while (lo <= hi)
            {
                int mid = lo + (hi - lo) / 2;
                byte* element = bytes + (long)mid * size;
                int order = cmp(instance, key, element);
                if (order < 0) hi = mid - 1;
                else if (order > 0) lo = mid + 1;
                else return element;
            }
            return null;
        }
        finally { context.Release(); }
    }
}


#nullable restore
// ---- StrchrnulLib.cs ----
#nullable enable

public static unsafe partial class Libc
{
    /// <summary>GNU strchrnul: find the first unsigned-byte match, returning
    /// the terminating NUL when the character is absent. No allocation, locale
    /// dependency, errno mutation, or read beyond the first NUL.</summary>
    public static byte* strchrnul(byte* text, int character)
    {
        byte value = unchecked((byte)character);
        while (*text != 0 && *text != value) text++;
        return text;
    }
}


#nullable restore
// ---- StringCopyLib.cs ----
#nullable enable


public static unsafe partial class Libc
{
    /// <summary>Copy through the NUL byte and return its address in destination.</summary>
    public static byte* stpcpy(byte* destination, byte* source)
    {
        while ((*destination = *source) != 0) { destination++; source++; }
        return destination;
    }

    /// <summary>Allocate an independent, NUL-terminated copy, released by free.
    /// Allocation failure returns NULL and sets ENOMEM; success preserves errno.</summary>
    public static byte* strdup(byte* source) => DuplicateStringBytes(source, strnlen(source, ulong.MaxValue));

    /// <summary>Read at most maximum source bytes, append NUL, and return a
    /// freeable independent copy. A large bound does not imply a large allocation.</summary>
    public static byte* strndup(byte* source, ulong maximum) => DuplicateStringBytes(source, strnlen(source, maximum));

    internal static byte* DuplicateStringBytes(byte* source, ulong length)
    {
        // Reserve the terminator before narrowing to the native allocation size.
        if (length >= (ulong)nuint.MaxValue) { errno = ENOMEM; return null; }
        byte* result = (byte*)AllocateHeap((nuint)length + 1);
        if (result == null) { errno = ENOMEM; return null; }
        if (length != 0) memcpy(result, source, length);
        result[length] = 0;
        return result;
    }
}


#nullable restore
// ---- StringLib.cs ----
#nullable enable



/// <summary>
/// C99 <c>&lt;string.h&gt;</c> surface beyond the three primitives that live in
/// <see cref="Libc"/> proper (<c>strlen</c> / <c>strcmp</c> / <c>strcpy</c> and
/// the <c>mem*</c> trio <c>memset</c> / <c>memcpy</c>). Every function is a bare
/// pointer loop over NUL-terminated UTF-8 <c>byte*</c> buffers — no GC
/// allocation, matching how real C code passes strings around.
/// </summary>
/// <remarks>
/// C <c>size_t</c> count arguments use <c>ulong</c> on dotcc's LP64 ABI.
/// Compatibility overloads retain the existing managed <c>int</c> callers.
/// The older string-size return APIs still return <c>int</c>; see C-SUPPORT.md.
/// Per dotcc's reentrant-by-default rule (see C-SUPPORT.md), the tokenizer
/// primitive is <see cref="strtok_r"/> (explicit <c>char**</c> save slot); the
/// C89 stateful <see cref="strtok"/> is a thin <c>[ThreadStatic]</c> wrapper.
/// </remarks>
public static unsafe partial class Libc
{
    /// <summary>POSIX bounded byte-string length. Never reads beyond the bound;
    /// a short terminated string also accepts bounds larger than Int32.MaxValue.</summary>
    public static ulong strnlen(byte* value, ulong maximum)
    {
        if (maximum != 0 && value == null) throw new ArgumentNullException(nameof(value));
        ulong length = 0;
        while (length < maximum && value[length] != 0) length++;
        return length;
    }

    // ---------------------------------------------------------------------
    // Comparison / copy — bounded variants
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strncmp(a, b, n)</c> — lexicographic compare of at most
    /// <paramref name="n"/> bytes. Stops early at a mismatch or a shared NUL.
    /// Takes <c>nuint</c> (C size_t) per the C standard. The <c>ulong</c>
    /// overload is for callers that have dotcc's <c>size_t</c> (= ulong).
    /// </summary>
    public static int strncmp(byte* a, byte* b, nuint n) => strncmp(a, b, (ulong)n);
    public static int strncmp(byte* a, byte* b, ulong n)
    {
        if (n != 0 && (a == null || b == null)) throw new ArgumentNullException(a == null ? nameof(a) : nameof(b));
        // A huge bound is valid for short terminated strings: do not validate a
        // fictitious n-byte allocation or narrow n before the early NUL check.
        while (n-- != 0)
        {
            if (*a != *b) return *a - *b;
            if (*a == 0) return 0;
            a++; b++;
        }
        return 0;
    }

    /// <summary>
    /// <c>strncpy(dst, src, n)</c> — copy up to <paramref name="n"/> bytes from
    /// <paramref name="src"/>. If <paramref name="src"/> is shorter, the
    /// remainder of <paramref name="dst"/> is NUL-padded to <paramref name="n"/>;
    /// if it is <paramref name="n"/> or longer, <em>no</em> terminating NUL is
    /// written (the classic C99 footgun, faithfully reproduced). Returns
    /// <paramref name="dst"/>.
    /// </summary>
    public static byte* strncpy(byte* dst, byte* src, int n) => strncpy(dst, src, checked((ulong)n));
    public static byte* strncpy(byte* dst, byte* src, ulong n)
    {
        nuint count = ValidateMemoryRange(dst, n);
        if (count != 0 && src == null) throw new ArgumentNullException(nameof(src));
        nuint i = 0;
        for (; i < count && src[i] != 0; i++) dst[i] = src[i];
        if (i < count) memset(dst + i, 0, (ulong)(count - i));
        return dst;
    }

    // ---------------------------------------------------------------------
    // Concatenation
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strcat(dst, src)</c> — append NUL-terminated <paramref name="src"/> to
    /// the end of NUL-terminated <paramref name="dst"/>, re-terminating. Returns
    /// <paramref name="dst"/>.
    /// </summary>
    public static byte* strcat(byte* dst, byte* src)
    {
        byte* p = dst;
        while (*p != 0) { p++; }
        while ((*p++ = *src++) != 0) { }
        return dst;
    }

    /// <summary>
    /// <c>strncat(dst, src, n)</c> — append at most <paramref name="n"/> bytes of
    /// <paramref name="src"/> to <paramref name="dst"/>, then always write a
    /// terminating NUL. Returns <paramref name="dst"/>.
    /// </summary>
    public static byte* strncat(byte* dst, byte* src, int n) => strncat(dst, src, checked((ulong)n));
    public static byte* strncat(byte* dst, byte* src, ulong n)
    {
        if (dst == null || (src == null && n != 0)) throw new ArgumentNullException(dst == null ? nameof(dst) : nameof(src));
        byte* p = dst;
        while (*p != 0) p++;
        while (n-- != 0 && *src != 0) *p++ = *src++;
        *p = 0;
        return dst;
    }

    // ---------------------------------------------------------------------
    // Search
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strchr(s, c)</c> — first occurrence of the byte
    /// <c>(byte)<paramref name="c"/></c> in <paramref name="s"/>, or <c>null</c>.
    /// The terminating NUL is part of the string, so <c>strchr(s, 0)</c> returns
    /// a pointer to it (per C).
    /// </summary>
    public static byte* strchr(byte* s, int c)
    {
        byte target = (byte)c;
        while (true)
        {
            if (*s == target) { return s; }
            if (*s == 0) { return null; }
            s++;
        }
    }

    /// <summary>
    /// <c>strrchr(s, c)</c> — last occurrence of <c>(byte)<paramref name="c"/></c>
    /// in <paramref name="s"/>, or <c>null</c>. <c>strrchr(s, 0)</c> finds the
    /// terminating NUL.
    /// </summary>
    public static byte* strrchr(byte* s, int c)
    {
        byte target = (byte)c;
        byte* last = null;
        while (true)
        {
            if (*s == target) { last = s; }
            if (*s == 0) { return last; }
            s++;
        }
    }

    /// <summary>
    /// <c>strstr(haystack, needle)</c> — pointer to the first occurrence of the
    /// NUL-terminated <paramref name="needle"/> substring within
    /// <paramref name="haystack"/>, or <c>null</c>. An empty needle returns
    /// <paramref name="haystack"/> (per C).
    /// </summary>
    public static byte* strstr(byte* haystack, byte* needle)
    {
        if (*needle == 0) { return haystack; }
        for (byte* h = haystack; *h != 0; h++)
        {
            byte* a = h;
            byte* b = needle;
            while (*a != 0 && *a == *b) { a++; b++; }
            if (*b == 0) { return h; }
        }
        return null;
    }

    /// <summary>
    /// <c>strspn(s, accept)</c> — length of the initial run of
    /// <paramref name="s"/> made up only of bytes that appear in
    /// <paramref name="accept"/>.
    /// </summary>
    public static int strspn(byte* s, byte* accept)
    {
        int n = 0;
        while (s[n] != 0 && InSet(accept, s[n])) { n++; }
        return n;
    }

    /// <summary>
    /// <c>strcspn(s, reject)</c> — length of the initial run of
    /// <paramref name="s"/> made up of bytes that do <em>not</em> appear in
    /// <paramref name="reject"/>.
    /// </summary>
    public static int strcspn(byte* s, byte* reject)
    {
        int n = 0;
        while (s[n] != 0 && !InSet(reject, s[n])) { n++; }
        return n;
    }

    /// <summary>
    /// <c>strpbrk(s, accept)</c> — pointer to the first byte of
    /// <paramref name="s"/> that appears in <paramref name="accept"/>, or
    /// <c>null</c> if none do.
    /// </summary>
    public static byte* strpbrk(byte* s, byte* accept)
    {
        for (; *s != 0; s++)
        {
            if (InSet(accept, *s)) { return s; }
        }
        return null;
    }

    /// <summary>Membership test of byte <paramref name="b"/> in the
    /// NUL-terminated set <paramref name="set"/> (the NUL itself is never a
    /// member — matches <c>strspn</c>/<c>strpbrk</c> semantics).</summary>
    private static bool InSet(byte* set, byte b)
    {
        for (byte* p = set; *p != 0; p++)
        {
            if (*p == b) { return true; }
        }
        return false;
    }

    // ---------------------------------------------------------------------
    // Tokenize — reentrant primitive + stateful wrapper
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>strtok_r(str, delim, saveptr)</c> — reentrant tokenizer. On the first
    /// call pass the string in <paramref name="str"/>; on continuation calls pass
    /// <c>null</c> and the same <paramref name="saveptr"/>. Writes NULs into the
    /// source buffer to terminate each returned token (destructive, like C).
    /// Returns the next token or <c>null</c> when exhausted.
    /// </summary>
    public static byte* strtok_r(byte* str, byte* delim, byte** saveptr)
    {
        byte* p = str != null ? str : *saveptr;
        if (p == null) { return null; }

        // Skip leading delimiters.
        while (*p != 0 && InSet(delim, *p)) { p++; }
        if (*p == 0) { *saveptr = p; return null; }

        byte* tokenStart = p;
        // Advance to the next delimiter (or end).
        while (*p != 0 && !InSet(delim, *p)) { p++; }
        if (*p != 0)
        {
            *p = 0;          // terminate this token in place
            *saveptr = p + 1;
        }
        else
        {
            *saveptr = p;    // reached end of string
        }
        return tokenStart;
    }

    [ThreadStatic]
    private static byte* _strtokSave;

    /// <summary>
    /// <c>strtok(str, delim)</c> — the C89 stateful tokenizer. A thin wrapper over
    /// <see cref="strtok_r"/> with a <c>[ThreadStatic]</c> save slot, so distinct
    /// threads don't clobber each other (real C's <c>strtok</c> uses one
    /// process-global cursor — not thread-safe). New code should prefer
    /// <see cref="strtok_r"/>.
    /// </summary>
    public static byte* strtok(byte* str, byte* delim)
    {
        fixed (byte** save = &_strtokSave)
        {
            return strtok_r(str, delim, save);
        }
    }

    // ---------------------------------------------------------------------
    // Memory — compare / move / find
    // ---------------------------------------------------------------------

    /// <summary>
    /// <c>memcmp(a, b, n)</c> — compare the first <paramref name="n"/> bytes.
    /// Returns the signed difference of the first differing pair (as
    /// <c>unsigned char</c>), or 0 if all <paramref name="n"/> bytes match.
    /// </summary>
    public static int memcmp(void* a, void* b, int n) => memcmp(a, b, checked((ulong)n));

    /// <summary>
    /// <c>memmove(dst, src, n)</c> — copy <paramref name="n"/> bytes,
    /// overlap-safe (unlike <see cref="Libc.memcpy"/>'s strict-no-overlap
    /// contract, though our memcpy is backed by the same overlap-safe primitive).
    /// Returns <paramref name="dst"/>.
    /// </summary>
    public static void* memmove(void* dst, void* src, int n) => memmove(dst, src, checked((ulong)n));

    /// <summary>
    /// <c>memchr(s, c, n)</c> — pointer to the first occurrence of
    /// <c>(byte)<paramref name="c"/></c> within the first <paramref name="n"/>
    /// bytes of <paramref name="s"/>, or <c>null</c>.
    /// </summary>
    public static void* memchr(void* s, int c, int n) => memchr(s, c, checked((ulong)n));
}


#nullable restore
// ---- ThreadsLib.cs ----
#nullable enable



/// <summary>
/// C11/C23 <c>&lt;threads.h&gt;</c> (§7.26) mapped onto
/// <see cref="System.Threading"/> — the <b>complete</b> surface: threads
/// (create/join/yield/current/equal/sleep/detach/exit), mutexes (plain /
/// recursive / timed), condition variables (<c>cnd_*</c>), thread-specific
/// storage (<c>tss_*</c> with per-thread-exit destructors), and
/// <c>call_once</c>. The opaque handle types <see cref="thrd_t"/> /
/// <see cref="mtx_t"/> / <see cref="cnd_t"/> / <see cref="tss_t"/> are blittable
/// value structs (a single id) so user code can stack-allocate them and take
/// their address; the managed objects live in side tables keyed by that id.
/// </summary>
/// <remarks>
/// <para>A C thread function returns <c>int</c>; .NET's <see cref="Thread"/>
/// has no return channel, so the result is stashed in the side table and
/// surfaced by <see cref="thrd_join"/>. The function pointer + arg are stored
/// as <see cref="IntPtr"/> and the body runs in a static entry method (a
/// lambda can't capture a function pointer).</para>
/// <para><b>Fidelity notes</b> (degraded, never silent): <c>tss_*</c>
/// destructors fire at the exit of a <c>thrd_create</c>-created thread but NOT
/// for the main / foreign threads (.NET has no per-thread-exit hook for those);
/// <c>thrd_exit</c> unwinds via a private sentinel exception caught in the entry
/// trampoline (there is no <c>Thread.Abort</c> on modern .NET), so it works from
/// a created thread but not the main thread; and <c>thrd_sleep</c> always sleeps
/// the full interval (dotcc has no async signal delivery, so it never reports a
/// remaining time). The timed calls take an absolute <c>TIME_UTC</c> deadline
/// (<c>mtx_timedlock</c> / <c>cnd_timedwait</c>) or a relative duration
/// (<c>thrd_sleep</c>), per C11.</para>
/// </remarks>
public static unsafe partial class Libc
{
    /// <summary>Opaque thread handle — just an id into <see cref="_threads"/>.</summary>
    public struct thrd_t { public int Id; }
    /// <summary>Opaque mutex handle — just an id into <see cref="_mtx"/>.</summary>
    public struct mtx_t { public int Id; }
    /// <summary>Opaque condition-variable handle — an id into <see cref="_cnd"/>.</summary>
    public struct cnd_t { public int Id; }
    /// <summary>Opaque thread-specific-storage key — an id into the per-thread
    /// value maps and the shared destructor table.</summary>
    public struct tss_t { public int Id; }

    // thrd_* return codes (values match glibc's <threads.h>).
    public const int thrd_success = 0;
    public const int thrd_busy = 1;
    public const int thrd_error = 2;
    public const int thrd_nomem = 3;
    public const int thrd_timedout = 4;

    // Mutex kinds. mtx_recursive is a flag bit that may be OR'd onto a base
    // (mtx_plain / mtx_timed), matching the C model.
    public const int mtx_plain = 0;
    public const int mtx_recursive = 1;
    public const int mtx_timed = 2;

    /// <summary>C11 <c>TSS_DTOR_ITERATIONS</c> — how many times the runtime retries
    /// thread-specific-storage destructors at thread exit (glibc's value).</summary>
    public const int TSS_DTOR_ITERATIONS = 4;

    private sealed class ThrdState
    {
        public IntPtr Func;   // (delegate*<void*,int>) stored as a pointer
        public IntPtr Arg;    // (void*)
        public int Result;
        public Thread? Thread;
        public RuntimeContext? Context;
        public bool Detached;
    }

    private sealed class MtxState
    {
        public int Type;
        public readonly SemaphoreSlim Avail = new(1, 1);
        public int Owner;   // managed-thread id of the current holder (recursive bookkeeping)
        public int Count;   // recursion depth
    }

    // A condition variable is a plain monitor object. cnd_wait enters this
    // monitor BEFORE releasing the caller's mutex, so a concurrent cnd_signal
    // (which must also enter the monitor to Pulse) cannot slip in between the
    // unlock and the wait — no lost wakeup, without reimplementing mtx.
    private sealed class CndState { public readonly object Lock = new(); }

    // thrd_exit unwinds the calling thread via this sentinel, caught in ThrdEntry
    // (modern .NET has no Thread.Abort). The exit code becomes the join result.
    private sealed class ThrdExitException : Exception { public int Code; }

    private static readonly ConcurrentDictionary<int, ThrdState> _threads = new();
    private static readonly ConcurrentDictionary<int, MtxState> _mtx = new();
    private static readonly ConcurrentDictionary<int, CndState> _cnd = new();
    // tss destructor per key (0 = none), shared across threads; the VALUES are
    // per-thread (each thread's own map, so distinct threads don't share slots).
    private static readonly ConcurrentDictionary<int, IntPtr> _tssDtors = new();
    [ThreadStatic] private static Dictionary<int, IntPtr>? _tssValues;
    // This thread's own thrd_t id (0 = not yet assigned). Set in the entry
    // trampoline for created threads; lazily minted by thrd_current otherwise.
    [ThreadStatic] private static int _selfThrdId;
    private static int _nextThrdId;
    private static int _nextMtxId;
    private static int _nextCndId;
    private static int _nextTssId;

    /// <summary>
    /// Spawn a thread running <paramref name="func"/>(<paramref name="arg"/>).
    /// The id is written into <paramref name="thr"/>; the int the function
    /// returns is captured for a later <see cref="thrd_join"/>.
    /// </summary>
    public static int thrd_create(thrd_t* thr, delegate*<void*, int> func, void* arg)
    {
        if (thr == null || func == null) { return thrd_error; }
        int id = Interlocked.Increment(ref _nextThrdId);
        RuntimeContext? context = RuntimeContext.Current;
        bool retained = false;
        try
        {
            if (context != null) { context.Retain(); retained = true; }
            var st = new ThrdState { Func = (IntPtr)func, Arg = (IntPtr)arg, Context = context };
            st.Thread = new Thread(ThrdEntry);
            _threads[id] = st;
            st.Thread.Start(id);
            thr->Id = id;
            return thrd_success;
        }
        catch (Exception error) when (error is OutOfMemoryException or ThreadStateException)
        {
            _threads.TryRemove(id, out _);
            if (retained) context!.Release();
            return error is OutOfMemoryException ? thrd_nomem : thrd_error;
        }
    }

    // Static entry — a lambda can't capture the function pointer, so the body
    // reads it from the side table by id (boxed through ParameterizedThreadStart).
    private static void ThrdEntry(object? idObj)
    {
        int id = (int)idObj!;
        var st = _threads[id];
        using var contextBinding = st.Context?.Enter();
        _selfThrdId = id;
        try
        {
            bool completed = false;
            try
            {
                try { st.Result = ((delegate*<void*, int>)st.Func)((void*)st.Arg); }
                catch (ThrdExitException ex) { st.Result = ex.Code; }
                completed = true;
            }
            finally
            {
                if (st.Context is null || (completed && st.Context.Termination is null))
                { RunPthreadDtors(); RunTssDtors(); }
            }
        }
        catch (Exception error) when (st.Context is not null)
        {
            st.Context.RecordWorkerFailure(error);
        }
        finally
        {
            if (st.Detached) { _threads.TryRemove(id, out _); }
            st.Context?.Release();
        }
    }

    // Run each thread-specific-storage destructor for a non-null value on this
    // thread, clearing the slot first (C11 §7.26.6.4), retrying up to
    // TSS_DTOR_ITERATIONS rounds since a dtor may set a fresh value.
    private static void RunTssDtors()
    {
        var vals = _tssValues;
        if (vals is null) { return; }
        for (var round = 0; round < TSS_DTOR_ITERATIONS; round++)
        {
            var any = false;
            foreach (var key in new List<int>(vals.Keys))
            {
                var v = vals[key];
                if (v == IntPtr.Zero) { continue; }
                if (!_tssDtors.TryGetValue(key, out var d) || d == IntPtr.Zero) { continue; }
                vals[key] = IntPtr.Zero;                     // clear BEFORE calling
                ((delegate*<void*, void>)d)((void*)v);
                any = true;
            }
            if (!any) { break; }
        }
    }

    // Convert a C11 absolute TIME_UTC deadline to a relative millisecond timeout
    // for the BCL wait primitives (clamped at 0 for an already-past deadline).
    private static int AbsTimeoutMs(timespec* ts)
    {
        long deadlineMs = ts->tv_sec * 1000L + ts->tv_nsec / 1_000_000L;
        long nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        long rel = deadlineMs - nowMs;
        return rel <= 0 ? 0 : (rel > int.MaxValue ? int.MaxValue : (int)rel);
    }

    /// <summary>Wait for <paramref name="thr"/> to finish; write its result to
    /// <paramref name="res"/> when non-null.</summary>
    public static int thrd_join(thrd_t thr, int* res)
    {
        if (!_threads.TryGetValue(thr.Id, out var st) || st.Thread is null) { return thrd_error; }
        st.Thread.Join();
        if (res != null) { *res = st.Result; }
        _threads.TryRemove(thr.Id, out _);
        return thrd_success;
    }

    /// <summary>Hint to the scheduler to yield the current thread's slice.</summary>
    public static void thrd_yield() => Thread.Yield();

    /// <summary>Initialise a mutex of the given <paramref name="type"/>.</summary>
    public static int mtx_init(mtx_t* mtx, int type)
    {
        if (mtx == null) { return thrd_error; }
        int id = Interlocked.Increment(ref _nextMtxId);
        _mtx[id] = new MtxState { Type = type };
        mtx->Id = id;
        return thrd_success;
    }

    /// <summary>Block until the mutex is held by the calling thread.</summary>
    public static int mtx_lock(mtx_t* mtx)
    {
        if (!_mtx.TryGetValue(mtx->Id, out var st)) { return thrd_error; }
        int me = Environment.CurrentManagedThreadId;
        if ((st.Type & mtx_recursive) != 0 && st.Owner == me) { st.Count++; return thrd_success; }
        st.Avail.Wait();
        st.Owner = me;
        st.Count = 1;
        return thrd_success;
    }

    /// <summary>Acquire without blocking; <see cref="thrd_busy"/> if already held.</summary>
    public static int mtx_trylock(mtx_t* mtx)
    {
        if (!_mtx.TryGetValue(mtx->Id, out var st)) { return thrd_error; }
        int me = Environment.CurrentManagedThreadId;
        if ((st.Type & mtx_recursive) != 0 && st.Owner == me) { st.Count++; return thrd_success; }
        if (!st.Avail.Wait(0)) { return thrd_busy; }
        st.Owner = me;
        st.Count = 1;
        return thrd_success;
    }

    /// <summary>Release one level of ownership.</summary>
    public static int mtx_unlock(mtx_t* mtx)
    {
        if (!_mtx.TryGetValue(mtx->Id, out var st)) { return thrd_error; }
        if ((st.Type & mtx_recursive) != 0 && --st.Count > 0) { return thrd_success; }
        st.Owner = 0;
        st.Avail.Release();
        return thrd_success;
    }

    /// <summary>Destroy a mutex and release its resources.</summary>
    public static void mtx_destroy(mtx_t* mtx)
    {
        if (_mtx.TryRemove(mtx->Id, out var st)) { st.Avail.Dispose(); }
    }

    /// <summary>Block until the mutex is held, or until the absolute
    /// <see cref="TIME_UTC"/> deadline <paramref name="ts"/> passes
    /// (<see cref="thrd_timedout"/>). Recursive re-entry by the owner succeeds
    /// immediately, like <see cref="mtx_lock"/>.</summary>
    public static int mtx_timedlock(mtx_t* mtx, timespec* ts)
    {
        if (!_mtx.TryGetValue(mtx->Id, out var st)) { return thrd_error; }
        int me = Environment.CurrentManagedThreadId;
        if ((st.Type & mtx_recursive) != 0 && st.Owner == me) { st.Count++; return thrd_success; }
        if (!st.Avail.Wait(AbsTimeoutMs(ts))) { return thrd_timedout; }
        st.Owner = me;
        st.Count = 1;
        return thrd_success;
    }

    /// <summary>Return the handle of the calling thread. A thread not created by
    /// <see cref="thrd_create"/> (e.g. the main thread) is lazily assigned a
    /// handle on first call.</summary>
    public static thrd_t thrd_current()
    {
        if (_selfThrdId == 0)
        {
            int id = Interlocked.Increment(ref _nextThrdId);
            _threads[id] = new ThrdState { Thread = Thread.CurrentThread };
            _selfThrdId = id;
        }
        return new thrd_t { Id = _selfThrdId };
    }

    /// <summary>Non-zero iff <paramref name="a"/> and <paramref name="b"/> name the
    /// same thread.</summary>
    public static int thrd_equal(thrd_t a, thrd_t b) => a.Id == b.Id ? 1 : 0;

    /// <summary>Sleep for the RELATIVE duration <paramref name="duration"/>. dotcc
    /// has no async signal delivery, so the full interval always elapses; on the
    /// (never-taken) interrupted path C returns the remaining time — here
    /// <paramref name="remaining"/> is zeroed and 0 (success) is returned.</summary>
    public static int thrd_sleep(timespec* duration, timespec* remaining)
    {
        if (duration == null) { return -1; }
        long ms = duration->tv_sec * 1000L + duration->tv_nsec / 1_000_000L;
        if (ms < 0) { ms = 0; }
        Thread.Sleep(ms > int.MaxValue ? int.MaxValue : (int)ms);
        if (remaining != null) { remaining->tv_sec = 0; remaining->tv_nsec = 0; }
        return 0;
    }

    /// <summary>Terminate the calling thread with result <paramref name="res"/>
    /// (available to <see cref="thrd_join"/>). Implemented by unwinding to the entry
    /// trampoline via a sentinel exception — works from a <see cref="thrd_create"/>
    /// thread; from the main thread it would propagate uncaught (see the fidelity
    /// notes).</summary>
    public static void thrd_exit(int res) => throw new ThrdExitException { Code = res };

    /// <summary>Detach <paramref name="thr"/> — its storage is reclaimed when it
    /// finishes and it can no longer be joined. If it has already finished, its
    /// side-table entry is removed now.</summary>
    public static int thrd_detach(thrd_t thr)
    {
        if (!_threads.TryGetValue(thr.Id, out var st)) { return thrd_error; }
        st.Detached = true;
        if (st.Thread is { IsAlive: false }) { _threads.TryRemove(thr.Id, out _); }
        return thrd_success;
    }

    // ── condition variables ────────────────────────────────────────────
    /// <summary>Initialise a condition variable.</summary>
    public static int cnd_init(cnd_t* cond)
    {
        if (cond == null) { return thrd_error; }
        int id = Interlocked.Increment(ref _nextCndId);
        _cnd[id] = new CndState();
        cond->Id = id;
        return thrd_success;
    }

    /// <summary>Wake one thread waiting on <paramref name="cond"/>.</summary>
    public static int cnd_signal(cnd_t* cond)
    {
        if (!_cnd.TryGetValue(cond->Id, out var st)) { return thrd_error; }
        lock (st.Lock) { Monitor.Pulse(st.Lock); }
        return thrd_success;
    }

    /// <summary>Wake all threads waiting on <paramref name="cond"/>.</summary>
    public static int cnd_broadcast(cnd_t* cond)
    {
        if (!_cnd.TryGetValue(cond->Id, out var st)) { return thrd_error; }
        lock (st.Lock) { Monitor.PulseAll(st.Lock); }
        return thrd_success;
    }

    /// <summary>Atomically release <paramref name="mtx"/> and block on
    /// <paramref name="cond"/>; re-acquire <paramref name="mtx"/> before returning.
    /// Entering the condition's monitor before unlocking the mutex closes the
    /// lost-wakeup window (a signaller must enter the same monitor to Pulse).</summary>
    public static int cnd_wait(cnd_t* cond, mtx_t* mtx)
    {
        if (!_cnd.TryGetValue(cond->Id, out var st)) { return thrd_error; }
        Monitor.Enter(st.Lock);
        mtx_unlock(mtx);
        Monitor.Wait(st.Lock);
        Monitor.Exit(st.Lock);
        mtx_lock(mtx);
        return thrd_success;
    }

    /// <summary>As <see cref="cnd_wait"/>, but give up at the absolute
    /// <see cref="TIME_UTC"/> deadline <paramref name="ts"/>
    /// (<see cref="thrd_timedout"/>); the mutex is re-acquired either way.</summary>
    public static int cnd_timedwait(cnd_t* cond, mtx_t* mtx, timespec* ts)
    {
        if (!_cnd.TryGetValue(cond->Id, out var st)) { return thrd_error; }
        Monitor.Enter(st.Lock);
        mtx_unlock(mtx);
        bool signalled = Monitor.Wait(st.Lock, AbsTimeoutMs(ts));
        Monitor.Exit(st.Lock);
        mtx_lock(mtx);
        return signalled ? thrd_success : thrd_timedout;
    }

    /// <summary>Destroy a condition variable.</summary>
    public static void cnd_destroy(cnd_t* cond) => _cnd.TryRemove(cond->Id, out _);

    // ── thread-specific storage ────────────────────────────────────────
    /// <summary>Create a TSS key with an optional destructor
    /// (<c>delegate*&lt;void*, void&gt;</c>, may be null). Each thread's value for
    /// the key starts null.</summary>
    public static int tss_create(tss_t* key, delegate*<void*, void> dtor)
    {
        if (key == null) { return thrd_error; }
        int id = Interlocked.Increment(ref _nextTssId);
        _tssDtors[id] = (IntPtr)dtor;
        key->Id = id;
        return thrd_success;
    }

    /// <summary>The calling thread's value for <paramref name="key"/> (null if
    /// unset).</summary>
    public static void* tss_get(tss_t key)
    {
        var vals = _tssValues;
        if (vals != null && vals.TryGetValue(key.Id, out var v)) { return (void*)v; }
        return null;
    }

    /// <summary>Set the calling thread's value for <paramref name="key"/>. Does NOT
    /// invoke the destructor on the replaced value (C11 §7.26.6.1).</summary>
    public static int tss_set(tss_t key, void* val)
    {
        (_tssValues ??= new Dictionary<int, IntPtr>())[key.Id] = (IntPtr)val;
        return thrd_success;
    }

    /// <summary>Release <paramref name="key"/> — no destructors are called and no
    /// thread's stored value is changed (C11 §7.26.6.2).</summary>
    public static void tss_delete(tss_t key) => _tssDtors.TryRemove(key.Id, out _);

    // ── call_once ──────────────────────────────────────────────────────
    /// <summary>Run <paramref name="func"/> exactly once for a given
    /// <paramref name="flag"/>, even under concurrent callers; the others block
    /// until the winner finishes. <c>once_flag</c> is a plain <c>int</c>
    /// (0 = pending, 1 = running, 2 = done; <c>ONCE_FLAG_INIT</c> = 0).</summary>
    public static void call_once(int* flag, delegate*<void> func)
    {
        if (Volatile.Read(ref *flag) == 2) { return; }
        if (Interlocked.CompareExchange(ref *flag, 1, 0) == 0)
        {
            func();
            Volatile.Write(ref *flag, 2);
        }
        else
        {
            while (Volatile.Read(ref *flag) != 2) { Thread.Yield(); }
        }
    }
}


#nullable restore
// ---- TimeLib.cs ----
#nullable enable



/// <summary>
/// C <c>&lt;time.h&gt;</c> scalar surface: <c>time</c> / <c>clock</c> /
/// <c>difftime</c>. <c>time_t</c> and <c>clock_t</c> lower (via plain typedefs
/// in the header) to C# <c>long</c>.
/// </summary>
/// <remarks>
/// The <c>struct tm</c> calendar family (<c>localtime</c> / <c>gmtime</c> /
/// <c>mktime</c> / <c>strftime</c> / <c>asctime</c> / <c>ctime</c>) lives in
/// <c>CalendarLib.cs</c>.
///
/// <para><c>clock()</c> returns a monotonic millisecond counter
/// (<see cref="Environment.TickCount64"/>) rather than true CPU time, with
/// <c>CLOCKS_PER_SEC</c> = 1000 — so the idiomatic
/// <c>(clock() - start) / (double)CLOCKS_PER_SEC</c> yields elapsed wall-clock
/// seconds. Avoiding <c>System.Diagnostics.Process</c> keeps the runtime block
/// lean.</para>
/// </remarks>
public static unsafe partial class Libc
{
    /// <summary><c>time(t)</c> — seconds since the Unix epoch (UTC). Stores the
    /// value through <paramref name="t"/> when non-null and also returns it.</summary>
    public static long time(long* t)
    {
        long secs = DateTimeOffset.UtcNow.ToUnixTimeSeconds();
        if (t != null) { *t = secs; }
        return secs;
    }

    /// <summary><c>clock()</c> — a monotonic millisecond counter (see remarks;
    /// pair with <c>CLOCKS_PER_SEC</c> = 1000). Use differences to measure
    /// elapsed time.</summary>
    public static long clock() => Environment.TickCount64;

    /// <summary><c>difftime(end, beginning)</c> — <c>end - beginning</c> as a
    /// <c>double</c> (seconds).</summary>
    public static double difftime(long end, long beginning) => (double)(end - beginning);

    /// <summary>C11 <c>struct timespec</c> (§7.27.1) — a whole-seconds + nanoseconds
    /// time value. A blittable value struct (like <see cref="tm"/>) so user code can
    /// stack-allocate it and take its address; <c>&lt;time.h&gt;</c> parses
    /// <c>struct timespec</c> via the usual <c>struct ID</c> rule (tag → this Libc
    /// type). Used by <c>timespec_get</c> and the <c>&lt;threads.h&gt;</c> timed calls
    /// (<c>thrd_sleep</c> / <c>mtx_timedlock</c> / <c>cnd_timedwait</c>).</summary>
    // CS8981: the all-lowercase name is deliberate — it must match the C type
    // `struct timespec` so `using static Libc;` resolves the emitted `timespec`.
#pragma warning disable CS8981
    public struct timespec { public long tv_sec; public long tv_nsec; }
#pragma warning restore CS8981

    /// <summary>C11 <c>TIME_UTC</c> time base for <see cref="timespec_get"/>.</summary>
    public const int TIME_UTC = 1;

    /// <summary><c>timespec_get(ts, base)</c> (C11 §7.27.2.5) — store the current
    /// time in <paramref name="ts"/> for the given <paramref name="base"/>. Only
    /// <see cref="TIME_UTC"/> is supported (UTC since the epoch); returns
    /// <paramref name="base"/> on success, 0 on an unsupported base or a null
    /// pointer. Nanoseconds come from the 100 ns tick resolution of the BCL clock.</summary>
    public static int timespec_get(timespec* ts, int @base)
    {
        if (ts == null || @base != TIME_UTC) { return 0; }
        var now = DateTimeOffset.UtcNow;
        ts->tv_sec = now.ToUnixTimeSeconds();
        ts->tv_nsec = (now.UtcTicks % TimeSpan.TicksPerSecond) * 100;   // 100 ns ticks → ns
        return @base;
