            for (int i = 0; i < max; i++) { _dst[i] = str[i]; }
            if (_capacity > 0) { _dst[max] = '\0'; }
            return -1;
        }
        for (int i = 0; i < str.Length; i++) { _dst[i] = str[i]; }
        if (_capacity > 0) { _dst[str.Length] = '\0'; }
        return str.Length;
    }
}


